/**
 * Picks one node of a hierarchy, in a field (`design/components/tree-select.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tree-select.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/popover'
import { normalizeProps } from '@zag-js/solid'

import {
  Icon,
  afresh,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  useMediaQuery,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/controls/tree-select.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import Tree, { type TreeItem, type TreeMessages } from '../structure/Tree'

export interface TreeSelectProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * The branches open at first, while the member holds the set.
   */
  defaultExpanded?: ReadonlySet<string>
  /**
   * Opens on mount. For galleries and tests; screens let the reader open it.
   */
  defaultOpen?: boolean
  /**
   * The node chosen at first, while the member holds the choice.
   */
  defaultValue?: string
  disabled?: boolean
  /**
   * Labels a selectable empty choice, drawn as the first top-level item. Choosing it reports
   * `null`, and the trigger shows this label as a value.
   */
  emptyOption?: string
  /**
   * The open branches by id. Controlled when given; without it the member holds the set.
   */
  expanded?: ReadonlySet<string>
  /**
   * The top level has more items than `items` holds: a last row asks for them.
   */
  hasMore?: boolean
  id?: string
  invalid?: boolean
  /**
   * Tree's items: the top level, each branch holding the level under it.
   */
  items: TreeItem[]
  /**
   * Names the tree in the popup, as Tree's `label` does: "Organization units". FormField names
   * the field.
   */
  label: string
  /**
   * The top level is loading, as an item's `loading` says of its own level.
   */
  loading?: boolean
  /**
   * Tree's strings, passed to the tree in the popup. Omit for Tree's English defaults.
   */
  messages?: TreeMessages
  /**
   * A hidden field that submits the chosen id, or the empty string for none and the empty
   * choice.
   */
  name?: string
  /**
   * Called with the id of the node a reader chooses, and `null` for the empty choice.
   */
  onChange?: (id: string | null) => void
  /**
   * Called with the next set of open branches, controlled or not.
   */
  onExpandedChange?: (next: ReadonlySet<string>) => void
  /**
   * Called with a branch's id, or `null` for the top level, when a reader asks for more.
   */
  onLoadMore?: (parentId: string | null) => void
  /**
   * Muted, and shown while no node is chosen. Cannot be combined with `emptyOption`.
   */
  placeholder?: string
  /**
   * `'auto'` shows the popup as a sheet below `30rem`, as Select's. `'popover'` keeps the
   * anchored popup at every width.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * The chosen node's id. Controlled when given. `null` is no node, and the empty choice when
   * `emptyOption` is set.
   */
  value?: string | null
  /**
   * What the trigger shows while the chosen node is not in `items`, because its level is not
   * loaded. A node in `items` is shown by its own label.
   */
  valueLabel?: string
}

/** Picks one node of a hierarchy, in a field. */
export default function TreeSelect(given: TreeSelectProps): JSX.Element {
  const props = mergeProps(
    {
      loading: false,
      hasMore: false,
      size: 'md',
      invalid: false,
      disabled: false,
      presentation: 'auto',
    } as Defaults<
      TreeSelectProps,
      'loading' | 'hasMore' | 'size' | 'invalid' | 'disabled' | 'presentation'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const sheetPanel = elementRef<HTMLElement>()
    const trigger = elementRef<HTMLElement>()
    const phone = useMediaQuery('phone')
    const ownValue = createCell((props.defaultValue ?? null) as string | null)
    const ownExpanded = createCell(
      props.defaultOpen === true
        ? ((
            tops: TreeItem[],
            held: ReadonlySet<string>,
            target: string | null,
          ): ReadonlySet<string> => {
            const walk = (level: TreeItem[], trail: string[]): string[] | null => {
              for (const node of level) {
                if (node.id === target) return trail
                const under =
                  node.children === undefined ? null : walk(node.children, [...trail, node.id])
                if (under !== null) return under
              }
              return null
            }
            const above = target === null ? null : walk(tops, [])
            return above === null || above.every((branch) => held.has(branch))
              ? held
              : new Set([...held, ...above])
          })(props.items, props.defaultExpanded ?? new Set<string>(), props.defaultValue ?? null)
        : (props.defaultExpanded ?? new Set<string>()),
    )
    const sheeting = createDerived(() => props.presentation === 'auto' && phone())
    const chosen = createDerived(() => (props.value === undefined ? ownValue.value : props.value))
    const branches = createDerived(() => props.expanded ?? ownExpanded.value)
    const emptyId = createDerived(() => `${uid}-empty`)
    const panelId = createDerived(() => `${uid}-panel`)
    const shownItems = createDerived(() =>
      props.emptyOption === undefined
        ? props.items
        : [{ id: emptyId.value, label: props.emptyOption }, ...props.items],
    )
    const treeValue = createDerived(
      () => chosen.value ?? (props.emptyOption === undefined ? null : emptyId.value),
    )
    const labelOf = createDerived(() => (level: TreeItem[], wanted: string): string | undefined => {
      for (const node of level) {
        if (node.id === wanted) return node.label
        const under = node.children === undefined ? undefined : labelOf.value(node.children, wanted)
        if (under !== undefined) return under
      }
      return undefined
    })
    const placeholderShown = createDerived(
      () => chosen.value === null && props.emptyOption === undefined,
    )
    const shown = createDerived(() =>
      chosen.value === null
        ? (props.emptyOption ?? props.placeholder ?? '')
        : (labelOf.value(props.items, chosen.value) ?? props.valueLabel ?? ''),
    )
    const changeExpanded = createDerived(() => (next: ReadonlySet<string>): void => {
      ownExpanded.value = next
      props.onExpandedChange?.(next)
    })
    const opened = createDerived(() => (now: boolean): void => {
      if (!now) return
      const next = ((
        tops: TreeItem[],
        held: ReadonlySet<string>,
        target: string | null,
      ): ReadonlySet<string> => {
        const walk = (level: TreeItem[], trail: string[]): string[] | null => {
          for (const node of level) {
            if (node.id === target) return trail
            const under =
              node.children === undefined ? null : walk(node.children, [...trail, node.id])
            if (under !== null) return under
          }
          return null
        }
        const above = target === null ? null : walk(tops, [])
        return above === null || above.every((branch) => held.has(branch))
          ? held
          : new Set([...held, ...above])
      })(props.items, branches.value, chosen.value)
      if (next !== branches.value) changeExpanded.value(next)
    })
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          defaultOpen: props.defaultOpen === true && !props.disabled,
          modal: true,
          positioning: { placement: 'bottom-start' as const, offset: { mainAxis: 2 } },
          ids: {
            ...(props.id === undefined ? {} : { trigger: props.id }),
            content: `${uid}-panel`,
          },
          initialFocusEl: () => {
            const box = sheetPanel.value ?? panel.value
            return (
              box?.querySelector<HTMLElement>(
                '[role="treeitem"][aria-selected="true"]:not([aria-disabled="true"])',
              ) ??
              box?.querySelector<HTMLElement>('[role="treeitem"]:not([aria-disabled="true"])') ??
              null
            )
          },
          onOpenChange: (details) => {
            opened.value(details.open)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const choose = createDerived(() => (picked: string): void => {
      const reported = picked === emptyId.value ? null : picked
      ownValue.value = reported
      props.onChange?.(reported)
      api.value.setOpen(false)
    })
    const openFromKeys = createDerived(() => (event: KeyboardEvent): void => {
      if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return
      event.preventDefault()
      if (!props.disabled) api.value.setOpen(true)
    })
    const closeOnRepick = createDerived(() => (event: Event): void => {
      const target = event.target instanceof Element ? event.target : null
      if (target === null) return
      if (event instanceof KeyboardEvent) {
        if (
          (event.key !== 'Enter' && event.key !== ' ') ||
          event.altKey ||
          event.ctrlKey ||
          event.metaKey
        )
          return
        if (target.closest('[role="treeitem"]')?.getAttribute('aria-selected') === 'true')
          api.value.setOpen(false)
        return
      }
      if (target.closest('[data-tree-part="toggle"]') !== null) return
      if (
        target.closest('[data-tree-part="row"]')?.parentElement?.getAttribute('aria-selected') ===
        'true'
      )
        api.value.setOpen(false)
    })
    const present = usePresence(
      () => api.value.open && !sheeting.value,
      () => panel.value,
    )
    const sheetPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => sheetPanel.value,
      'sheet.panel',
      { sheetSide: 'bottom' },
    )
    const scrimPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => scrim.value,
      'dialog.scrim',
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'TreeSelect',
        element: () => trigger.value,
        state: () => ({
          value:
            chosen.value === null ? (props.emptyOption === undefined ? null : '') : chosen.value,
          options: [
            ...(props.emptyOption === undefined ? [] : [{ id: '', label: props.emptyOption }]),
            ...((
              level: TreeItem[],
            ): (Pick<TreeItem, 'id' | 'label'> & Partial<Record<'disabled', true>>)[] => {
              const out: (Pick<TreeItem, 'id' | 'label'> & Partial<Record<'disabled', true>>)[] = []
              const walk = (nodes: TreeItem[], off: boolean): void => {
                for (const node of nodes) {
                  const shut = off || node.disabled === true
                  out.push({
                    id: node.id,
                    label: node.label,
                    ...(shut ? { disabled: true as const } : {}),
                  })
                  if (node.children !== undefined) walk(node.children, shut)
                }
              }
              walk(level, false)
              return out
            })(props.items),
          ],
          open: api.value.open,
          disabled: props.disabled,
          invalid: props.invalid,
        }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) =>
              (value === '' ? null : value) === chosen.value ||
              choose.value(value === '' ? emptyId.value : value),
          },
          open: () => api.value.setOpen(true),
          close: () => api.value.setOpen(false),
        },
        withholds: () => sheetPanel.value ?? panel.value,
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <>
        {/* trigger */}
        <button
          {...mergeParts(api.value.getTriggerProps(), {
            class: styles.trigger,
            role: 'combobox',
            'aria-haspopup': 'tree',
            'aria-controls': api.value.open ? panelId.value : undefined,
            'aria-label': props['aria-label'],
            'aria-labelledby': props['aria-labelledby'],
            'aria-describedby': props['aria-describedby'],
            'aria-required': props['aria-required'],
            'aria-invalid': props.invalid ? true : undefined,
            disabled: props.disabled ? true : undefined,
            'data-size': props.size,
            'data-invalid': props.invalid ? '' : undefined,
            'data-disabled': props.disabled ? '' : undefined,
            'data-placeholder': placeholderShown.value ? '' : undefined,
            'data-member': 'tree-select',
            onkeydown: ($event: KeyboardEvent) => openFromKeys.value($event),
          })}
          ref={trigger.attach}
        >
          <span class={styles.value}>{shown.value}</span>
          <span class={styles.chevron} aria-hidden="true">
            <Icon name="expand" size={props.size} />
          </span>
        </button>
        {props.name !== undefined ? (
          <input
            type="hidden"
            name={props.name}
            value={chosen.value ?? ''}
            disabled={props.disabled ? true : undefined}
          />
        ) : null}
        <Portal>
          {afresh(() => (
            <>
              {present() ? (
                <div {...mergeParts(api.value.getPositionerProps())}>
                  {/* panel */}
                  <div
                    {...mergeParts(api.value.getContentProps(), {
                      class: styles.content,
                      style: {
                        '--radix-popover-trigger-width': 'var(--reference-width)',
                        '--radix-popover-content-available-width': 'var(--available-width)',
                        '--radix-popover-content-available-height': 'var(--available-height)',
                        '--radix-popover-content-transform-origin': 'var(--transform-origin)',
                      },
                      hidden: undefined,
                      role: undefined,
                      'aria-modal': undefined,
                      'aria-labelledby': undefined,
                      'aria-describedby': undefined,
                      'data-size': props.size,
                      'data-member': 'tree-select',
                      onkeydown: ($event: KeyboardEvent) => closeOnRepick.value($event),
                      onclick: ($event: MouseEvent) => closeOnRepick.value($event),
                    })}
                    ref={panel.attach}
                  >
                    <Tree
                      label={props.label}
                      items={shownItems.value}
                      expanded={branches.value}
                      value={treeValue.value}
                      loading={props.loading}
                      hasMore={props.hasMore}
                      messages={props.messages}
                      onChange={($event) => choose.value($event)}
                      onExpandedChange={($event) => changeExpanded.value($event)}
                      onLoadMore={($event) => props.onLoadMore?.($event)}
                    />
                  </div>
                </div>
              ) : null}
              {scrimPresent() ? (
                <div
                  class={sheet.scrim}
                  data-state={api.value.open ? 'open' : 'closed'}
                  ref={scrim.attach}
                />
              ) : null}
              {sheetPresent() ? (
                <div class={sheet.positioner}>
                  <div
                    {...mergeParts(api.value.getContentProps(), {
                      class: sheet.panel,
                      hidden: undefined,
                      role: undefined,
                      'aria-modal': undefined,
                      'aria-labelledby': undefined,
                      'aria-describedby': undefined,
                      'data-presentation': 'sheet',
                    })}
                    ref={sheetPanel.attach}
                  >
                    {/* sheetBody */}
                    <div
                      class={styles.sheetBody}
                      data-size={props.size}
                      data-member="tree-select"
                      onkeydown={($event: KeyboardEvent) => closeOnRepick.value($event)}
                      onclick={($event: MouseEvent) => closeOnRepick.value($event)}
                    >
                      <Tree
                        label={props.label}
                        items={shownItems.value}
                        expanded={branches.value}
                        value={treeValue.value}
                        loading={props.loading}
                        hasMore={props.hasMore}
                        messages={props.messages}
                        onChange={($event) => choose.value($event)}
                        onExpandedChange={($event) => changeExpanded.value($event)}
                        onLoadMore={($event) => props.onLoadMore?.($event)}
                      />
                    </div>
                  </div>
                </div>
              ) : null}
            </>
          ))}
        </Portal>
      </>
    )
  })
}
